L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "\227\129\169\227\129\134\227\129\155\232\178\160\227\129\145\227\130\139\227\130\147\227\129\160\227\128\130\228\189\147\232\170\191\227\129\174\227\129\155\227\129\132\227\129\167\232\168\128\227\129\132\232\168\179\227\129\153\227\130\139\229\167\191\227\129\175\232\166\139\227\129\159\227\129\143\227\129\170\227\129\132\227\129\139\227\130\137\227\129\170\227\128\130"
