L16_1.m_Talk_SCN = "\229\155\160\228\184\186\228\189\160\230\179\168\229\174\154\232\166\129\232\190\147\239\188\140\229\143\175\229\136\171\230\156\128\229\144\142\230\137\190\231\144\134\231\148\177\239\188\140\232\175\180\228\187\128\228\185\136\229\155\160\228\184\186\231\151\133\228\186\134\230\137\141\232\190\147\230\142\137\227\128\130"
